   int added=owner.equals(PC)?3:owner.endsWith("$Cube")||owner.endsWith("$StatusLease")||owner.endsWith("$Event")||owner.endsWith("$BindLease")||owner.endsWith("$MrLease")?1:0;need(after.methods.size()==before.methods.size()+added,"only original wrappers/metadata overloads");
   for(var m:after.methods)if(before.methods.stream().noneMatch(x->x.name.equals(m.name)&&x.desc.equals(m.desc))&&!m.name.startsWith("nativeSourceCubeStatusOriginal")){for(var n:m.instructions)if(n instanceof MethodInsnNode call)need(Set.of(N,O,P+"NativeSourceCubeNpc",PC,owner).contains(call.owner),"typed same original constructor/body plus metadata only");}
