  need(fresh.equals(Set.of(N+".class",N+"$Link.class",N+"$Emission.class")),"one helper and two detached metadata records");System.out.println("PASS independent Quake-Shock inverse: "+methods+" original methods; exact original geometry/cost/clocks/mutations and fallback; immutable final lease index, no new worker/TLS/SQL/HP queue");
